//! The range checks — `check_video`, `check_audio`, `check_text` and
//! `check_shape`, one per property group — and the bounds they check
//! against. They answer one question: is this props struct, as it stands,
//! within the ranges the inspector can show (spec §4.3)?
//!
//! Cut out of `edit_props.rs` in phase 2 under the size rule
//! (core/CLAUDE.md: a module over ~600 lines gives something up before it
//! takes anything on — `set_clip` and `check_group` took that file to
//! 619), and cut HERE because a range check is a fact about the
//! VOCABULARY, not about an edit. It reads a finished `VideoProps` and says
//! whether the numbers are legal, and it neither knows nor cares whether a
//! patch (`edit_props.rs`), a paste (`edit_paste.rs`), a new title or shape
//! (`edit_described.rs`) or a canvas colour (`edit_track.rs`) produced them.
//! Every op that writes a group runs that group's check after writing and
//! before storing, so these four functions are the ONE statement of what a
//! legal group is — and `actions_clamp.rs`'s `clamp_video` bounds an
//! interpolated value against the same constants, which is why the bounds
//! live with the checks and not in any one op.
//!
//! The rule behind every check is `edit_props.rs`'s third: values are
//! NAMED, never clamped. A channel outside 0–1 is a units mistake (0–255)
//! and a scale of 50 is a typo; the message names the dotted key and the
//! offending value, so the caller — a typed Swift builder, an MCP call, or
//! a payload written by hand — sees the number that was refused. The
//! bounds themselves are the inspector's (spec §4.3), so a value this
//! module accepts is a value a control can show.
//!
//! Every reader names this module directly — `edit_props.rs` for the four
//! checks, `edit_described.rs` for the two a new title or shape runs,
//! `edit_track.rs` for `color_ok`, `actions.rs` for the bounds — and nothing
//! re-exports it, so a grep for its name finds every place a bound is read.

use crate::audio::MAX_GAIN;
use crate::audio_dynamics::{
    check_compressor, check_de_esser, check_gate, check_leveller, check_limiter,
};
use crate::audio_eq::{check_eq, check_hum};
use crate::grade_check::{check_curves, check_qualifier, check_wheels};
use crate::model::{
    AudioProps, Color, ShapeProps, TextProps, VideoProps, MAX_FILTERS, MAX_GRADIENT_STOPS,
    MAX_OBSCURE,
};
use crate::model_words::token_count;
use crate::time::Ticks;
use crate::time_bounds::MAX_STORED_TICKS;

// ---- bounds --------------------------------------------------------------

/// Scale range, matching the inspector's 1–1000 % (spec §4.3). The lower
/// bound is not 0: a zero scale is an invisible layer that looks like a
/// broken render, and `opacity` is the way to hide something.
pub(crate) const SCALE_MIN: f64 = 0.01;
pub(crate) const SCALE_MAX: f64 = 10.0;

/// The most a spotlight may magnify what is inside it — spec §4.2's
/// "optional 1.2–2× zoom". Past 2× the region is soft: the pixels are
/// coming from the same decoded frame, and nothing creates detail.
pub(crate) const SPOT_ZOOM_MAX: f64 = 2.0;

/// The compressor's bounds (spec §4.3, "smooth volume levels"). The
/// threshold floor is -60 dBFS because below it there is nothing but noise
/// to compress; 20:1 is a limiter, which is as far as a "smooth the levels"
/// control should be able to go; and 24 dB of makeup is enough to bring a
/// heavily compressed voice back to full scale and no more.
pub(crate) const COMPRESSOR_THRESHOLD_MIN_DB: f64 = -60.0;
pub(crate) const COMPRESSOR_RATIO_MAX: f64 = 20.0;
pub(crate) const COMPRESSOR_MAKEUP_MAX_DB: f64 = 24.0;

/// The clip limiter's bounds (spec §11 AU-21). A ceiling from −24 dBTP,
/// past which it is a level control rather than a limiter, up to full
/// scale; a release of 1 ms to 1 s, in ticks.
pub(crate) const LIMITER_CEILING_MIN_DB: f64 = -24.0;
pub(crate) const LIMITER_RELEASE_MIN: Ticks = 600;
pub(crate) const LIMITER_RELEASE_MAX: Ticks = 600_000;

/// Where a word-caption page's active word may settle (format version 9,
/// road map 8 §5a). 1 is "no pop"; past 1.5 the active word crowds its
/// neighbours on a page the pager filled to a measured width.
pub(crate) const WORD_SCALE_MIN: f64 = 1.0;
pub(crate) const WORD_SCALE_MAX: f64 = 1.5;

/// Tone's bounds (spec §11 GR-2): exposure is ±3 EV, and the other eight
/// are ±1 — fade 0…1 — at the strengths `Compositor.metal`'s `gradeTone`
/// gives them.
pub(crate) const EXPOSURE_MAX: f64 = 3.0;
pub(crate) const TONE_MAX: f64 = 1.0;

// ---- range checks --------------------------------------------------------

pub(crate) fn finite(key: &str, value: f64) -> Result<(), String> {
    if value.is_finite() {
        Ok(())
    } else {
        Err(format!("{key} must be a finite number, not {value}"))
    }
}

pub(crate) fn in_range(key: &str, value: f64, low: f64, high: f64) -> Result<(), String> {
    if value.is_finite() && value >= low && value <= high {
        Ok(())
    } else {
        Err(format!(
            "{key} must be between {low} and {high}, not {value}"
        ))
    }
}

fn at_least(key: &str, value: f64, low: f64) -> Result<(), String> {
    if value.is_finite() && value >= low {
        Ok(())
    } else {
        Err(format!("{key} must be at least {low}, not {value}"))
    }
}

fn above(key: &str, value: f64, low: f64) -> Result<(), String> {
    if value.is_finite() && value > low {
        Ok(())
    } else {
        Err(format!("{key} must be greater than {low}, not {value}"))
    }
}

/// Colors are `[r, g, b, a]` floats 0–1 (spec §5.2); a channel outside that
/// is a unit mistake (0–255) the renderer would turn into a blown-out
/// layer, so it is named rather than clamped.
pub(crate) fn color_ok(key: &str, color: &Color) -> Result<(), String> {
    for channel in color {
        in_range(key, *channel, 0.0, 1.0)?;
    }
    Ok(())
}

/// A clip-time position inside D7-1's envelope, in `time_bounds.rs`'s own
/// words — a word time is a position, so it may be negative.
fn ticks_in_envelope(key: &str, value: Ticks) -> Result<(), String> {
    if (-MAX_STORED_TICKS..=MAX_STORED_TICKS).contains(&value) {
        Ok(())
    } else {
        Err(format!(
            "{key} must be between -{MAX_STORED_TICKS} and {MAX_STORED_TICKS} ticks, not {value}"
        ))
    }
}

pub(crate) fn ticks_in_range(
    key: &str,
    value: Ticks,
    low: Ticks,
    high: Ticks,
) -> Result<(), String> {
    if (low..=high).contains(&value) {
        Ok(())
    } else {
        Err(format!(
            "{key} must be between {low} and {high} ticks, not {value}"
        ))
    }
}

pub(crate) fn ticks_positive_or_zero(key: &str, value: Ticks) -> Result<(), String> {
    if value >= 0 {
        Ok(())
    } else {
        Err(format!("{key} must not be negative, not {value}"))
    }
}

/// The video group. `size` is the source's pixel size when it is known, so
/// a crop can be checked against the thing being cropped.
pub(crate) fn check_video(props: &VideoProps, size: Option<(f64, f64)>) -> Result<(), String> {
    finite("video.x", props.x)?;
    finite("video.y", props.y)?;
    in_range("video.scale", props.scale, SCALE_MIN, SCALE_MAX)?;
    finite("video.rotation", props.rotation)?;
    in_range("video.opacity", props.opacity, 0.0, 1.0)?;
    at_least("video.corner_radius", props.corner_radius, 0.0)?;
    at_least("video.crop.l", props.crop.l, 0.0)?;
    at_least("video.crop.t", props.crop.t, 0.0)?;
    at_least("video.crop.r", props.crop.r, 0.0)?;
    at_least("video.crop.b", props.crop.b, 0.0)?;
    // Opposite edges must leave something behind: a crop that meets or
    // crosses is an empty rectangle, which no renderer can draw.
    if let Some((width, height)) = size {
        let horizontal = props.crop.l + props.crop.r;
        if horizontal >= width {
            return Err(format!(
                "video.crop l + r must be less than the source width {width}, not {horizontal}"
            ));
        }
        let vertical = props.crop.t + props.crop.b;
        if vertical >= height {
            return Err(format!(
                "video.crop t + b must be less than the source height {height}, not {vertical}"
            ));
        }
    }
    // Motion (format version 8). The two edge values are DURATIONS, so 0 is
    // legal — it means that end of the clip does not move — and a negative
    // one is a sign mistake, not a request to run the preset backwards;

//! The property patches — `set_video`, `set_audio`, `set_text`, `set_shape`
//! and, for the clip's own name and label, `set_clip` (spec §6, the "Clips"
//! table). The range checks that police everything written into a clip's
//! property groups are `props_check.rs`'s, cut out of here in phase 2;
//! this file runs them after every merge and restates none of them.
//!
//! This is the schema half of editing, split off from `edit_clip.rs`'s
//! placement half: nothing here moves a clip in time or on a track, and
//! nothing here decides what a clip IS. It answers one question — is this
//! patch a legal description of this group, and what does the group look
//! like once it is merged in?
//!
//! Three things run through all of it:
//!
//! 1. **A patch is a subset of one group**, read by `patch.rs`'s
//!    [`merge_group`] — the walk of keys and JSON kinds against the group's
//!    template, the deep merge and the typed read back, so a field is
//!    patchable the moment `model.rs` declares it and there is no second
//!    list of patchable keys to forget to update. That module was cut out
//!    of this one under the size rule, and it holds every sentence about
//!    what a patch may CARRY; nothing here restates them.
//! 2. **A mistake is named, never dropped.** A typed Swift builder and an
//!    MCP call both reach these ops, and a key silently dropped here is a
//!    bug the user would never see.
//! 3. **Values are named, never clamped.** A channel outside 0–1 is a units
//!    mistake (0–255) and a scale of 50 is a typo; silently clamping them
//!    would leave the user looking at a number the inspector did not
//!    accept. The one deliberate exception is `set_speed`, which lives in
//!    `edit_clip.rs` and clamps because a slider asking for ×20 wants the
//!    fastest thing available.
//!
//! The bounds themselves, and the four checks against them, are
//! `props_check.rs`'s (the inspector's numbers, spec §4.3): a value that
//! passes there is a value a control can show, and a merge here is stored
//! only once its group has passed. Exactly one check stays behind —
//! [`check_blend`], which refuses a blend mode on a nest clip — because it
//! is a fact about the CLIP and not about the vocabulary, and nothing in
//! `props_check.rs` is handed a clip to ask.

use serde_json::Value;

use crate::edit_adjustment::{check_adjustment_video, check_qualifier_clip};
use crate::edit_clip_timing::{SPEED_MAX, SPEED_MIN};
use crate::export::describe;
use crate::lut::normalise_look;
use crate::model::{BlendMode, Clip, Project, Source, TextProps, VideoProps};
use crate::outcome::Outcome;
use crate::patch::{merge_group, Group, GROUPS};
use crate::props_check::{check_audio, check_shape, check_text, check_video};

/// The one check a video group cannot make on its own: a NEST clip may not
/// carry a blend mode (format version 6).
///
/// A nest is FLATTENED rather than composited offscreen (`nest.rs`), so
/// there is no such thing as "the nest's picture" for a blend to combine
/// with what is under it — each clip inside contributes its own layer, and a
/// blend on the nest clip could only mean "blend every one of them
/// separately against whatever happens to be below". That is a different
/// picture from the one the popup promises, and a wrong picture is worse
/// than a refusal.
///
/// **Only a non-normal MERGED value fires**, which is not leniency for its
/// own sake. `paste_attributes` replaces the video group WHOLE, so a check
/// on any MENTION of the key would fail an all-or-nothing paste of an
/// ordinary look — one that never touched blend — onto a nest clip, for a
/// value that changes nothing. `{"blend": "normal"}` on a nest clip is
/// therefore the identity and answers [`Outcome::Identity`] through the
/// usual `finish`.
///
/// It lives HERE rather than in `props_check.rs` because it is not a fact
/// about the vocabulary: the value is perfectly legal and it is the CLIP it
/// was written onto that refuses it, where `props_check.rs` never sees a
/// clip. Both callers — the patch path and every pasted video group — run
/// it inside [`Project::settle_video`], so the two give the identical message.
///
/// It is not the whole story either: `set_action_end` checks the VOCABULARY
/// and never the clip, and a blend mode is a legal value, so an end patch
/// can still carry one onto a nest clip. `actions_clamp.rs`'s `clamp_video` is
/// what closes that door, for the recipe, `clip_state` and both export
/// writers at once.
fn check_blend(clip: &Clip, props: &VideoProps) -> Result<(), String> {
    if props.blend != BlendMode::Normal && matches!(clip.source, Source::Nest { .. }) {
        return Err(format!(
            "clip {} shows a nest and cannot take a blend mode",
            clip.id
        ));
    }
    Ok(())
}

/// `set_audio`'s one refusal of a legal value (spec §11 AU-111).
const NEEDS_SPEECH: &str =
    "audio.duck.mode speech needs the clip's media to carry speech spans (set_media_speech)";

/// Whether the PATCH itself sets `duck.mode` to `speech` — read from the
/// patch and never from the merged props, so a clip already holding a
/// spanless speech duck (Paste Attributes makes one) keeps every other
/// audio edit (spec §11 AU-111).
fn sets_speech_duck(patch: &Value) -> bool {
    patch.pointer("/duck/mode").and_then(Value::as_str) == Some("speech")
}

// ---- the ops -------------------------------------------------------------

impl Project {
    /// Merges `patch` into every named clip's video props (spec §6).
    /// An identity when nothing changes; `Err` for an unknown clip, a clip
    /// with no video props, an unknown key, or a value out of range.
    pub fn set_video(&self, clips: &[u32], patch: &Value) -> Result<Outcome, String> {
        self.patch_clips(clips, patch, Group::Video)
    }

    /// Merges `patch` into every named clip's audio props (spec §6). A patch
    /// setting `duck.mode` to `speech` is refused on a clip that is not a
    /// media clip or whose media has no `speech` (spec §11 AU-111).
    pub fn set_audio(&self, clips: &[u32], patch: &Value) -> Result<Outcome, String> {
        self.patch_clips(clips, patch, Group::Audio)
    }

    /// Whether `clip` is a media clip whose media carries `speech`.
    fn has_speech(&self, clip: &Clip) -> bool {
        let Source::Media { media, .. } = clip.source else {
            return false;
        };
        self.media(media).is_some_and(|m| m.speech.is_some())
    }

    /// Merges `patch` into every named text clip's text props (spec §6).
    pub fn set_text(&self, clips: &[u32], patch: &Value) -> Result<Outcome, String> {
        self.patch_clips(clips, patch, Group::Text)
    }

    /// Merges `patch` into every named shape clip's shape props (spec §6).
    pub fn set_shape(&self, clips: &[u32], patch: &Value) -> Result<Outcome, String> {
        self.patch_clips(clips, patch, Group::Shape)
    }

    /// Sets or clears every named clip's own name and label (spec §6) — the
    /// fifth patch op, shaped like `set_video` so that "absent keeps, null
    /// clears" lives where it already does in this crate: inside a patch
    /// object, never as an `Option<T>` envelope argument, where absent and
    /// null decode alike. The keys are `name` and `label`, each a string or `null`.
    /// A string is stored trimmed, and an EMPTY one — after trimming — clears
    /// too: `set_track`'s rule for a name, except that "unnamed" is `None`
    /// here, so the app's fallback name returns. `Err` for an unknown clip,
    /// an unknown key, or a value that is neither a string nor `null`;
    /// an identity when nothing changes.
    pub fn set_clip(&self, clips: &[u32], patch: &Value) -> Result<Outcome, String> {
        let Some(fields) = patch.as_object() else {
            return Err(format!(
                "clip patch must be a json object, not {}",
                describe(patch)
            ));
        };
        // The outer `Option` is "was the key given"; the inner is what to
        // store, `None` for a clear.
        let mut name: Option<Option<String>> = None;
        let mut label: Option<Option<String>> = None;
        for (key, value) in fields {
            let slot = match key.as_str() {
                "name" => &mut name,
                "label" => &mut label,
                other => return Err(format!("unknown key \"{other}\" in a clip patch")),
            };
            *slot = Some(match value {
                Value::Null => None,
                Value::String(text) => Some(text.trim())
                    .filter(|t| !t.is_empty())
                    .map(String::from),
                other => {
                    return Err(format!(
                        "\"{key}\" in a clip patch must be a string or null, not {}",
                        describe(other)
                    ))
                }
            });
        }
        let ids: Vec<u32> = self.selected_clips(clips)?.iter().map(|c| c.id).collect();

        let mut next = self.clone();
        for id in ids {
            if let Some(slot) = next.clip_mut(id) {
                if let Some(name) = &name {
                    slot.name = name.clone();
                }
                if let Some(label) = &label {
                    slot.label = label.clone();
                }
            }
        }
        self.finish(next)
    }

    /// Puts a motion preset's two edge durations and its `during` period on
    /// the document's frame grid — the core's Times rule (core/CLAUDE.md:
    /// every tick value that reaches the model is snapped first) applied at
    /// the patch door, where before D1·2 a comment in `props_check.rs` said
    /// "the inspector snaps" and left an agent's value sub-frame.
    ///
    /// It runs AFTER the range check, so a refusal names the number the
    /// caller actually sent: a `duration` of −1 is a sign mistake and is
    /// refused, where snapping first would have turned it into a legal 0 and
    /// said nothing. Snapping cannot undo that check — a non-negative
    /// duration snaps to a non-negative one — with one exception, and
    /// `period` carries its own floor for it: it divides in every `during`
    /// formula, so a period under half a frame would snap to 0 and stop the
    /// motion the caller asked for. On the grid the smallest period there
    /// is is one frame, so that is where it lands.
    pub(crate) fn snap_motion(&self, props: &mut VideoProps) {
        let Some(motion) = props.motion.as_mut() else {
            return;
        };
        for edge in [motion.r#in.as_mut(), motion.out.as_mut()]
            .into_iter()
            .flatten()
        {
            edge.duration = self.snapped(edge.duration);
        }
        if let Some(during) = motion.during.as_mut() {
            during.period = self.snapped(during.period).max(self.frame());
        }
    }

    /// The same for a text animation's two timings ([`Self::snap_motion`]
    /// argues the order and the rounding). Both are DURATIONS, so 0 is
    /// legal and a reveal shorter than half a frame lands there: it is a
    /// reveal no frame could show.
    ///
    /// It snaps every `text.words[i].start` and `end` too (format version
    /// 9, spec §11's W-3): a word time is a clip time like any other a patch
    /// carries, so it lands on the grid AFTER `check_text` has named what
    /// the caller sent. Nearest, never clamped — a negative start is legal
    /// ("already said") and stays negative. Two words may land on one
    /// frame, which the check allows and the recipe resolves (the later
    /// one wins that frame).
    ///
    /// `pub(crate)` for the one text patch that is not `set_text`:
    /// `add_text_clip`'s, which runs the same merge and the same check in
    /// `edit_clip.rs` and must land on the same grid.
    pub(crate) fn snap_animation(&self, props: &mut TextProps) {
        for word in &mut props.words {
            word.start = self.snapped(word.start);
            word.end = self.snapped(word.end);
        }
        let Some(animation) = props.animation.as_mut() else {
            return;
        };
        animation.r#in = self.snapped(animation.r#in);
        animation.out = self.snapped(animation.out);
    }

    /// The chain that makes a video group storable — `set_video`'s and every
    /// pasted video group's (issue #349), so a group written by hand into a
    /// clipboard payload meets exactly what a patch meets, in the same
    /// order and with the same sentences.
    ///
    /// 1. **One spelling of "no motion"** (format version 8, road map 5
    ///    §5a): a patch that clears the last filled slot leaves a `Motion`
    ///    with three `None`s behind, and a payload's `{"motion": {}}` or
    ///    three explicit nulls deserialise to the same thing; either would
    ///    round-trip as `{"in": null, "out": null, "during": null}` and make
    ///    two equal clips compare unequal. It is normalised HERE rather than
    ///    in serde, because the deep merge is what produces the empty one —
    ///    a caller who writes `{"motion": {}}` means the same thing and gets
    ///    the same answer. The invariant stays open only at the FILE reader,
    ///    which keeps the long spelling on purpose until a patch touches it
    ///    (`core/tests/schema_v8.rs`'s
    ///    `a_motion_whose_slots_are_all_cleared_normalises_back_to_null`;
    ///    road map 7 §2.2).
    /// 2. The vocabulary's ranges (`check_video`), on the values the caller
    ///    sent.
    /// 3. An identity curve is stored as none (spec §11 GR-12), AFTER the
    ///    range check so a malformed identity-shaped curve is still refused
    ///    by name; an identity curve on an uncurved clip is then an identity.
    /// 4. The rules about this CLIP rather than the values — [`check_blend`],
    ///    the adjustment and qualifier rules, the cutout's clip kinds (spec
    ///    §11 CO-20), Behind Subject's (CO-52), motion blur's (CU-111), the
    ///    look's media.
    /// 5. Motion timings snapped to the grid ([`Self::snap_motion`]).
    ///
    /// The look's own normalisation (`normalise_look`) is the patch path's
    /// alone: it reads the PATCH, which a pasted group does not have.
    pub(crate) fn settle_video(&self, clip: &Clip, props: &mut VideoProps) -> Result<(), String> {
        if props.motion.is_some_and(|motion| motion.is_empty()) {
            props.motion = None;
        }
        check_video(props, self.source_size(clip))?;
        props.curves.drop_identities();
        check_blend(clip, props)?;
        check_adjustment_video(clip, props)?;
        check_qualifier_clip(clip, props)?;
        crate::cutout_check::check_cutout_clip(clip, props)?;
        crate::cutout_check::check_behind_subject_clip(clip, props)?;
        crate::motion_blur::check_motion_blur_clip(clip, props)?;
        self.check_hide_silent_clip(clip, props)?;
        self.check_look_media(props)?;
        self.snap_motion(props);
        Ok(())
    }

    /// What `paste_attributes` runs on each group it has just replaced, and
    /// `paste` on every group of every clip it lands
    /// ([`Self::normalise_and_check_pasted`]), so a payload written by hand
    /// meets the bounds a patch does and a group `paste_attributes` did not
    /// touch is not its business. A video group goes through
    /// [`Self::settle_video`], `set_video`'s own chain; the other three
    /// through the same `check_audio` / `check_text` / `check_shape` the
    /// patch path calls, a text group's timings then snapped to the
    /// destination grid. A group the clip lacks has nothing to check.
    pub(crate) fn normalise_and_check_group(
        &self,
        clip: &mut Clip,
        group: Group,
    ) -> Result<(), String> {
        match group {
            Group::Video => {
                if let Some(mut video) = clip.video.clone() {
                    self.settle_video(clip, &mut video)?;
                    clip.video = Some(video);
                }
            }
            Group::Audio => {
                if let Some(audio) = clip.audio.as_ref() {
                    check_audio(audio)?;
                }
            }
            Group::Text => {
                if let Some(text) = clip.text.as_mut() {
                    check_text(text)?;
                    self.snap_animation(text);
                }
            }
            Group::Shape => {
                if let Some(shape) = clip.shape.as_ref() {
                    check_shape(shape)?;
                }
            }
        }
        Ok(())
    }

    /// The clip's speed against `SPEED_MIN`–`SPEED_MAX`, then every group of
    /// one clip `paste` is about to land, through
    /// [`Self::normalise_and_check_group`] in [`GROUPS`] order, so a payload
    /// written by hand meets the bounds a patch does (issue #62, #206). A
    /// failure names the id the PAYLOAD gave the clip, the only one its
    /// writer knows. The callers have already reset a non-finite or
    /// non-positive speed to 1. The clip's own times are the caller's to
    /// re-snap, after this, at the speed checked here.
    pub(crate) fn normalise_and_check_pasted(
        &self,
        clip: &mut Clip,
        payload_id: u32,
    ) -> Result<(), String> {
        // Spelled as JSON spells it, as `validate`'s speed sentence is.
        if !(SPEED_MIN..=SPEED_MAX).contains(&clip.speed) {
            return Err(format!(
                "pasted clip {payload_id}: speed {} is outside ×{SPEED_MIN}–×{SPEED_MAX}",
                serde_json::Value::from(clip.speed)
            ));
        }
        for group in GROUPS {
            self.normalise_and_check_group(clip, group)
                .map_err(|why| format!("pasted clip {payload_id}: {why}"))?;
        }
        Ok(())
    }

    /// The one implementation behind the four `set_*` property ops: merge,
    /// check the keys against the group's schema, deserialize, range-check,
    /// store.
    ///
    /// A clip that does not HAVE the group is an error, not a silent skip:
    /// the group's presence is what "this clip has audio" / "this is a text
    /// clip" means, and inventing it would put text props on a video clip.
    fn patch_clips(&self, clips: &[u32], patch: &Value, group: Group) -> Result<Outcome, String> {
        if !patch.is_object() {
            return Err(format!(
                "{} patch must be a json object, not {}",
                group.name(),
                describe(patch)
            ));
        }
        let ids: Vec<u32> = self.selected_clips(clips)?.iter().map(|c| c.id).collect();
        if ids.is_empty() {
            return Ok(Outcome::Identity);
        }

        let mut next = self.clone();
        for id in ids {
            let clip = match next.clip(id) {
                Some(clip) => clip.clone(),
                None => continue,
            };
            match group {
                Group::Video => {
                    let base = clip
                        .video
                        .clone()
                        .ok_or_else(|| format!("clip {id} has no video properties"))?;
                    let mut props = merge_group(&base, patch, group)?;
                    normalise_look(&mut props, patch)?;
                    self.settle_video(&clip, &mut props)?;
                    if let Some(slot) = next.clip_mut(id) {
                        slot.video = Some(props);
                    }
                }
                Group::Audio => {
                    let base = clip
                        .audio
                        .ok_or_else(|| format!("clip {id} has no audio properties"))?;
                    let props = merge_group(&base, patch, group)?;
                    check_audio(&props)?;
                    if sets_speech_duck(patch) && !self.has_speech(&clip) {
                        return Ok(Outcome::Refused(NEEDS_SPEECH.to_string()));
                    }
                    if let Some(slot) = next.clip_mut(id) {
                        slot.audio = Some(props);
                    }
                }
                Group::Text => {
                    let base = clip
                        .text
                        .clone()
                        .ok_or_else(|| format!("clip {id} has no text properties"))?;
                    let mut props = merge_group(&base, patch, group)?;
                    check_text(&props)?;
                    self.snap_animation(&mut props);
                    if let Some(slot) = next.clip_mut(id) {
                        slot.text = Some(props);
                    }
                }
                Group::Shape => {
                    let base = clip
                        .shape
                        .clone()
                        .ok_or_else(|| format!("clip {id} has no shape properties"))?;
                    let props = merge_group(&base, patch, group)?;
                    check_shape(&props)?;
                    if let Some(slot) = next.clip_mut(id) {
                        slot.shape = Some(props);
                    }
                }
            }
        }
        self.finish(next)
    }
}

