164	    in_range("audio.volume", props.volume, 0.0, MAX_GAIN)?;
165	    ticks_positive_or_zero("audio.fade_in", props.fade_in)?;
166	    ticks_positive_or_zero("audio.fade_out", props.fade_out)?;
167	    if let Some(duck) = &props.duck {
168	        in_range("audio.duck.level", duck.level, 0.0, 1.0)?;
169	        ticks_positive_or_zero("audio.duck.attack", duck.attack)?;
170	        ticks_positive_or_zero("audio.duck.release", duck.release)?;
171	        ticks_positive_or_zero("audio.duck.pre_roll", duck.pre_roll)?;
172	        ticks_positive_or_zero("audio.duck.hold", duck.hold)?;
173	    }
174	    in_range("audio.pan", props.pan, -1.0, 1.0)?;
175	    in_range("audio.noise_reduction", props.noise_reduction, 0.0, 1.0)?;
176	    in_range("audio.isolation", props.isolation, 0.0, 1.0)?;
177	    if let Some(compressor) = &props.compressor {
178	        check_compressor("audio.compressor", compressor)?;
179	    }
180	    if let Some(limiter) = &props.limiter {
181	        check_limiter("audio.limiter", limiter)?;
182	    }
183	    props.eq.as_ref().map(check_eq).transpose()?;
184	    props.hum.as_ref().map(check_hum).transpose()?;
185	    props.gate.as_ref().map(check_gate).transpose()?;
186	    props.de_esser.as_ref().map(check_de_esser).transpose()?;
187	    props.leveller.as_ref().map(check_leveller).transpose()?;
188	    if let Some(voice) = &props.voice {
189	        in_range("audio.voice.amount", voice.amount, 0.0, 1.0)?;
190	        if let Some(pitch) = voice.pitch {
191	            in_range("audio.voice.pitch", pitch, -12.0, 12.0)?;
192	        }
193	    }
194	    Ok(())
195	}
