197	pub(crate) fn check_text(props: &TextProps) -> Result<(), String> {
198	    above("text.size", props.size, 0.0)?;
199	    color_ok("text.color", &props.color)?;
200	    above("text.line_spacing", props.line_spacing, 0.0)?;
201	    finite("text.tracking", props.tracking)?;
202	    if let Some(outline) = &props.outline {
203	        at_least("text.outline.width", outline.width, 0.0)?;
204	        color_ok("text.outline.color", &outline.color)?;
205	    }
206	    if let Some(backdrop) = &props.backdrop {
207	        color_ok("text.backdrop.color", &backdrop.color)?;
208	        at_least("text.backdrop.padding", backdrop.padding, 0.0)?;
209	        at_least("text.backdrop.radius", backdrop.radius, 0.0)?;
210	    }
211	    if let Some(width) = props.width {
212	        above("text.width", width, 0.0)?;
213	    }
214	    if let Some(animation) = &props.animation {
215	        // Both are durations, so 0 is legal — it means that end of the
216	        // animation does not happen — and a negative one is a sign
217	        // mistake, not a request to run the reveal backwards. `Ticks` is an
218	        // `i64`, so "finite" is the type's job and only the sign is left
219	        // for a check to make. They are snapped to the frame grid by
220	        // `edit_props.rs`'s `snap_animation`, after this check and for the
221	        // motion arm's reason above. The KIND needs none: serde refuses an
222	        // unknown variant on the way in, which is what closing the enum
223	        // bought (`model_props.rs`).
224	        ticks_positive_or_zero("text.animation.in", animation.r#in)?;
225	        ticks_positive_or_zero("text.animation.out", animation.out)?;
226	    }
227	    // Word timings (format version 9, spec §11 W-2 and W-3). The core is
228	    // the one counter: a non-empty list must hold one timing per
229	    // whitespace token, and it is never padded or trimmed to fit. Each
230	    // time is a clip-time POSITION, so a negative one is legal ("already
231	    // said", what `split` leaves on a second half) and only D7-1's envelope
232	    // bounds it. Equal starts are legal too — two engine words snapped to
233	    // one frame — so the order rule is non-decreasing, and a word may be
234	    // zero-length. These run on what the caller sent; `edit_props.rs`'s
235	    // `snap_animation` snaps them after, so a refusal names that number.
236	    if !props.words.is_empty() {
237	        let tokens = token_count(&props.content);
238	        if props.words.len() != tokens {
239	            return Err(format!(
240	                "this text is timed word by word: {} timings for {tokens} words",
241	                props.words.len()
242	            ));
243	        }
244	    }
245	    for (i, word) in props.words.iter().enumerate() {
246	        ticks_in_envelope(&format!("text.words[{i}].start"), word.start)?;
247	        ticks_in_envelope(&format!("text.words[{i}].end"), word.end)?;
248	        if word.end < word.start {
249	            return Err(format!(
250	                "text.words[{i}].end must be at least its start {}, not {}",
251	                word.start, word.end
252	            ));
253	        }
254	        if i > 0 && word.start < props.words[i - 1].start {
255	            return Err(format!(
256	                "text.words[{i}].start must not precede text.words[{}].start {}, not {}",
257	                i - 1,
258	                props.words[i - 1].start,
259	                word.start
260	            ));
261	        }
262	    }
263	    if let Some(style) = &props.word_style {
264	        in_range(
265	            "text.word_style.active_scale",
266	            style.active_scale,
267	            WORD_SCALE_MIN,
268	            WORD_SCALE_MAX,
269	        )?;
270	        if let Some(color) = &style.active_color {
271	            color_ok("text.word_style.active_color", color)?;
272	        }
273	        if let Some(color) = &style.spoken_color {
274	            color_ok("text.word_style.spoken_color", color)?;
275	        }
276	        if let Some(color) = &style.upcoming_color {
277	            color_ok("text.word_style.upcoming_color", color)?;
278	        }
279	        if let Some(pill) = &style.active_pill {
280	            color_ok("text.word_style.active_pill.color", &pill.color)?;
281	            at_least("text.word_style.active_pill.padding", pill.padding, 0.0)?;
282	            at_least("text.word_style.active_pill.radius", pill.radius, 0.0)?;
283	        }
284	        in_range("text.word_style.pause_dim", style.pause_dim, 0.0, 1.0)?;
285	    }
286	    Ok(())
287	}
