289	pub(crate) fn check_shape(props: &ShapeProps) -> Result<(), String> {
290	    above("shape.width", props.width, 0.0)?;
291	    above("shape.height", props.height, 0.0)?;
292	    at_least("shape.radius", props.radius, 0.0)?;
293	    if let Some(stroke) = &props.stroke {
294	        at_least("shape.stroke.width", stroke.width, 0.0)?;
295	        color_ok("shape.stroke.color", &stroke.color)?;
296	    }
297	    if let Some(fill) = &props.fill {
298	        color_ok("shape.fill", fill)?;
299	    }
300	    for point in [&props.from, &props.to] {
301	        for coordinate in point {
302	            finite("shape.from/to", *coordinate)?;
303	        }
304	    }
305	    if let Some(gradient) = &props.gradient {
306	        // Two stops is the floor because ONE stop is a solid colour, and
307	        // `shape.fill` already spells a solid colour. `CGGradient` would
308	        // happily draw a single stop, which is exactly why the refusal is
309	        // here: a control that quietly becomes a different control is worse
310	        // than one that says no.
311	        if gradient.stops.len() < 2 {
312	            return Err(format!(
313	                "shape.gradient.stops must hold at least 2 stops, not {}",
314	                gradient.stops.len()
315	            ));
316	        }
317	        // The ceiling is NAMED rather than trimmed, the posture `MAX_FILTERS`
318	        // and `MAX_OBSCURE` take — but it is 8 where both of those are 4, and
319	        // `MAX_GRADIENT_STOPS`' own doc argues why: those two are shader
320	        // slots and this one is not a budget at all.
321	        if gradient.stops.len() > MAX_GRADIENT_STOPS {
322	            return Err(format!(
323	                "shape.gradient.stops must hold at most {MAX_GRADIENT_STOPS} stops, not {}",
324	                gradient.stops.len()
325	            ));
326	        }
327	        // There is deliberately NO ordering check here, and it is the one
328	        // absence in this module worth writing down. `CGGradient` requires
329	        // monotonic locations or its output is undefined, so the temptation
330	        // is to refuse an unsorted list — but a refusal has a failure mode
331	        // nobody would accept: dragging one stop past another is how a
332	        // gradient is edited, and the drag would stop working halfway
333	        // through. `video.filters` is the precedent — an ordered list the
334	        // core does not police — and the fix belongs where the requirement
335	        // is, so `LayerRenderers.renderShape` sorts before it draws.
336	        // And the question is a RENDER-time one only, which is what keeps
337	        // the answer small: a gradient is never interpolated, because shape
338	        // props are not animatable at all (`actions.rs::evaluate_clip`
339	        // builds its merge state from `video`, `audio` and `text`, and
340	        // passes `shape` through untouched — spec §5.4). So an unsorted list is
341	        // only ever DRAWN, once, by a renderer that sorts it first. Do not
342	        // read this as "the list rule handles it"; there is no list rule in
343	        // play here, and if shapes ever become animatable the ordering
344	        // question has to be asked again against `lerp`.
345	        for (i, stop) in gradient.stops.iter().enumerate() {
346	            in_range(&format!("shape.gradient.stops[{i}].at"), stop.at, 0.0, 1.0)?;
347	            color_ok(&format!("shape.gradient.stops[{i}].color"), &stop.color)?;
348	        }
349	        // Finite and nothing more, exactly as `video.shadow.angle` is: the
350	        // value is named and never clamped, and wrapping it into 0..360 here
351	        // would silently rewrite the number a person typed.
352	        finite("shape.gradient.angle", gradient.angle)?;
353	    }
354	    Ok(())
355	}
