pub struct ObscureRegion {
    pub shape: SpotShape,
    pub x: f64,
    pub y: f64,
    pub width: f64,
    pub height: f64,
    /// Source pixels the effect is ramped in over; 0 is a hard edge.
    pub feather: f64,
    pub kind: ObscureKind,
    /// 0 = the region is there but hides nothing, 1 = its full effect.
